function cancelTwins(s: string): string {
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < s.length; i++) {
      if (s[i] === s[i + 1]) {
        s = s.slice(0, i) + s.slice(i + 2);
        changed = true;
        break;
      }
    }
  }
  return s;
}

